import{_ as a,a as e,b as o,c as r,d as t,e as l,f as n,g as s,h as c,i as p}from"./chunks/CAL11.DuBx0sYj.js";import{_ as d}from"./chunks/hamburger_menu.BLyto8gA.js";import{_ as m}from"./chunks/BDM.scaBLLhv.js";import{_ as u,o as b,c as g,a3 as v}from"./chunks/framework.g9mfNVRQ.js";const C=JSON.parse('{"title":"Calibra","description":"","frontmatter":{"source_hash":"b31e419e7a","source_commit":"7a18e7c","i18n_outdated":true},"headers":[],"relativePath":"it/calibrate/calibrate.md","filePath":"it/calibrate/calibrate.md"}'),h={name:"it/calibrate/calibrate.md"};function z(f,i,_,x,q,P){return b(),g("div",null,[...i[0]||(i[0]=[v('<div class="warning custom-block"><p class="custom-block-title">Calibrazione</p><p>Non fidarti mai ciecamente di un sensore di glicemia: verifica regolarmente le letture con una glicemia capillare.<br> Una linea piatta (sempre lo stesso numero) <strong>non</strong> è mai un buon segno.</p></div><h3 id="general-considerations" tabindex="-1">Considerazioni generali <a class="header-anchor" href="#general-considerations" aria-label="Permalink to &quot;Considerazioni generali {#general-considerations}&quot;">​</a></h3><p>La calibrazione è fondamentale per la precisione delle misure del CGM. Usa sempre un glucometro affidabile e mettiti nelle condizioni migliori per avere la misura capillare più precisa possibile quando calibri.</p><p>Alcuni dei prerequisiti più importanti sono:</p><ol><li><strong>Glicemia stabile.</strong> Non calibrare mai quando la glicemia sale o scende rapidamente.</li><li><strong>Nell&#39;intervallo (importante per la calibrazione iniziale di Libre).</strong> Cerca di eseguire le calibrazioni quando la glicemia è nell&#39;intervallo normale (80-180 mg/dl o 5-10 mmol/l).</li><li><strong>Non calibrare troppo.</strong> Meglio poche calibrazioni precise che troppe: molto probabilmente confonderesti xDrip. Per G6, G7, 1, 1+ segui le raccomandazioni del produttore.</li></ol><h3 id="native-and-xdrip-algorithms" tabindex="-1">Algoritmo nativo e algoritmo di xDrip <a class="header-anchor" href="#native-and-xdrip-algorithms" aria-label="Permalink to &quot;Algoritmo nativo e algoritmo di xDrip {#native-and-xdrip-algorithms}&quot;">​</a></h3><p>xDrip può fornire i propri algoritmi di calibrazione per i sensori che inviano dati grezzi.</p><p>Con la calibrazione nativa di G6, G7, 1, 1+, xDrip non usa il proprio algoritmo ma invia i valori di calibrazione al trasmettitore, lasciando che li gestisca con il suo algoritmo proprietario.</p><p>I sensori Libre 1, 14 giorni, Pro, 2 (UE) e 2+ (UE) inviano solo dati grezzi e hanno bisogno o della calibrazione di xDrip o di un plugin di calibrazione esterno chiamato <a href="./../use/OOP.html">algoritmo OOP (out of process algorithm)</a>.</p><p>L&#39;app modificata Libre 2 usa il proprio algoritmo proprietario (anche se in una versione vecchia).</p><table tabindex="0"><thead><tr><th>Sensore</th><th>Calibrazione xDrip</th><th>Calibrazione nativa</th></tr></thead><tbody><tr><td>G6 con batteria sostituita</td><td>Disponibile</td><td>Disponibile</td></tr><tr><td>G6, G7, 1, 1+</td><td>Non disponibile</td><td>Obbligatoria</td></tr><tr><td>Libre 1</td><td>Obbligatoria</td><td>OOP1 (obsoleto)</td></tr><tr><td>Libre 2 UE app modificata</td><td>Scostamento limitato (vedi sotto)</td><td>Per costruzione</td></tr><tr><td>Libre 2/2+ UE, Libre 14 giorni USA</td><td><a href="./../use/OOP.html#oop2">Facoltativa</a></td><td>OOP2</td></tr></tbody></table><h5 id="libre-2-patched-app" tabindex="-1">App modificata Libre 2 <a class="header-anchor" href="#libre-2-patched-app" aria-label="Permalink to &quot;App modificata Libre 2 {#libre-2-patched-app}&quot;">​</a></h5><p>Con l&#39;app modificata puoi calibrare, ma la correzione viene applicata come scostamento (offset) con valori massimi tra -40 mg/dl e +20 mg/dL [-2,2 mmol/l e +1,1 mmol/l]. Le calibrazioni che non rispettano questi criteri vengono <strong>ignorate</strong>.</p><h3 id="xdrip-calibration-settings" tabindex="-1">Impostazioni di calibrazione di xDrip <a class="header-anchor" href="#xdrip-calibration-settings" aria-label="Permalink to &quot;Impostazioni di calibrazione di xDrip {#xdrip-calibration-settings}&quot;">​</a></h3><div class="warning custom-block"><p class="custom-block-title">Solo calibrazione xDrip</p><p>Le informazioni qui sotto riguardano la calibrazione di xDrip.<br> Per la modalità nativa di G6/G7/1/1+ vedi <a href="https://navid200.github.io/xDrip/docs/Dexcom_page.html" target="_blank" rel="noreferrer">qui</a>.</p></div><p>Prima di calibrare controlla le tue <a href="./advancedcal.html">impostazioni</a>.</p><p>Una cosa che conviene attivare sono le <a href="./../use/lesscommon.html#show-data-tables">tabelle dati</a> nel menu principale. Ti aiuteranno davvero a capire quando qualcosa va storto.</p><h3 id="first-calibration" tabindex="-1">Prima calibrazione <a class="header-anchor" href="#first-calibration" aria-label="Permalink to &quot;Prima calibrazione {#first-calibration}&quot;">​</a></h3><p>Se il tuo sensore richiede calibrazioni, dopo averlo collegato a xDrip e aver ricevuto tre valori dovresti vedere questa richiesta:</p><div class="admonition xdripitem"><p class="admonition-title">Calibrare il sensore?</p><p> Abbiamo alcune letture!</p><p> Ci servirà il valore della prima misura capillare.</p><p> Pronto per calibrare ora?</p><p> NO    <span style="background-color:white;color:black;"> CALIBRA </span></p></div><p>I due valori di calibrazione iniziali sono un&#39;eredità del G4. Se vuoi usarli correttamente, esegui due misure diverse (due strisce): è l&#39;approccio consigliato. Se di solito inserisci lo stesso valore, puoi renderlo predefinito <a href="./advancedcal.html#calibrations">qui</a>.</p><div class="admonition xdrip"><p class="admonition-title">☰ Calibrazione iniziale</p><p> <u>Inserisci Primo Valore Glicemia</u><br>  <u>Inserisci Secondo Valore Glicemia</u></p><p> <small>Per iniziare, si prega di effettuare due test della Glicemia e inserire i valori qui!</small></p></div><p>Se usi la calibrazione nativa, il valore viene inviato al trasmettitore per l&#39;elaborazione.</p><p>Se usi la calibrazione di xDrip, questo valore viene elaborato 10 minuti dopo, per compensare tutti i ritardi fisiologici e chimici della misura del CGM: <strong>per questo è estremamente importante calibrare con glicemia stabile</strong>.</p><p>Vediamo graficamente cosa succede nella schermata principale:</p><ol><li>Prima lettura (riportata al valore di calibrazione)</li><li>Seconda lettura (riportata al valore di calibrazione)</li><li>Non ancora visibile, ma è la terza lettura: il valore effettivo al momento della calibrazione</li><li>Lettura successiva tra 5 minuti</li><li>Lettura successiva tra 10 minuti e punto di calibrazione (che verrà usato tra 10 minuti)</li></ol><img src="'+a+'"><p>Se la glicemia è rimasta stabile in questo periodo, dovresti vederla passare per il punto di calibrazione.</p><img src="'+e+'"><p>Nella tabella dati di calibrazione vedrai nuove voci che corrispondono alle misure di glicemia grezza usate per definire la calibrazione:</p><ol><li>È il valore che hai inserito (convertito in mg/dl se necessario)</li><li>Stesso valore, ma nell&#39;unità che usi con xDrip (qui in mg/dl, ma comparirà anche in mmol/l)</li><li>Glicemia grezza del sensore</li><li>Pendenza e intercetta calcolate</li><li>Data e ora effettive della calibrazione (cioè l&#39;ora reale + 10 minuti) e data e ora della glicemia grezza corrispondente</li><li>Per una calibrazione ci sono due serie di misure di dati grezzi: una più bassa, una più alta</li></ol><img src="'+o+'" style="zoom:75%;"><p>Il grafico di calibrazione sarà ora più o meno così.<br> A seconda della differenza tra i campioni di sangue e della variabilità della glicemia attuale, la pendenza potrebbe non essere esattamente 1.</p><img src="'+r+'" style="zoom:75%;"><h3 id="successive-calibrations" tabindex="-1">Calibrazioni successive <a class="header-anchor" href="#successive-calibrations" aria-label="Permalink to &quot;Calibrazioni successive {#successive-calibrations}&quot;">​</a></h3><p>Per sicurezza controllerai regolarmente la tua glicemia reale, almeno una volta al giorno, perché non puoi fidarti ciecamente di un sensore. Inserisci queste glicemie capillari come <a href="./../use/mainUI.html#treatments">trattamenti</a>.<br> Perché i valori di glicemia non varino troppo rapidamente, non dovresti calibrare quando in quel momento hai carboidrati o insulina attivi.</p><div class="info custom-block"><p class="custom-block-title">Frequenza</p><p>A meno che il tuo sensore non lo richieda espressamente, non calibrare sistematicamente ogni volta che fai una glicemia capillare.<br> Per i sensori Libre, non è necessario calibrare se la differenza è inferiore al 15%.</p></div><p><strong>Non calibrare troppo</strong>: puoi fare tutte le glicemie capillari che vuoi e inserirle come trattamenti in xDrip, ma aggiungi calibrazioni con particolare attenzione.</p><p>Nel grafico di calibrazione vedrai i punti di calibrazione attivi in blu e quelli vecchi o non validi in grigio.</p><img src="'+t+'" style="zoom:75%;"><p>Se, con glicemia stabile, confrontando il valore di xDrip 10 minuti dopo la glicemia capillare, vedi che il valore è troppo diverso, aggiungerai un altro punto di calibrazione.</p><p>Poiché l&#39;andamento della glicemia è spesso difficile da prevedere, puoi usare un trucco:</p><ul><li>Verifica che Usa i valori di glicemia dei trattamenti non sia impostato su Never Use Them in <a href="./advancedcal.html">Calibrazione avanzata</a>.</li><li>Inserisci la glicemia capillare come trattamento.</li></ul><img src="'+l+'" style="zoom:75%;"><ul><li>Attendi 10 minuti e valuta se sarebbe stato un buon momento per calibrare (glicemia abbastanza stabile).</li></ul><img src="'+n+'" style="zoom:75%;"><ul><li>Se lo era, tocca il trattamento (la nuova glicemia capillare, punto quadrato bianco sul grafico) e trasformalo in una calibrazione.</li></ul><div class="admonition xdripitem"><p class="admonition-title">Azione su misura capillare</p><p> Che cosa vorresti fare?</p><p> NIENTE CANCELLA   <span style="background-color:white;color:black;"> CALIBRA </span></p></div><p>Ora hai un altro punto di calibrazione.</p><img src="'+s+'" style="zoom:75%;"><h3 id="disable-a-calibration" tabindex="-1">Disattivare una calibrazione <a class="header-anchor" href="#disable-a-calibration" aria-label="Permalink to &quot;Disattivare una calibrazione {#disable-a-calibration}&quot;">​</a></h3><p>Può succedere che un punto di calibrazione sia chiaramente sbagliato e che tu voglia eliminarlo.</p><p>Apri la Tabella dati di calibrazione e <strong>tieni premuta</strong> la calibrazione che vuoi disattivare.</p><img src="'+c+'" style="zoom:75%;"><div class="admonition xdripitem"><p class="admonition-title">Disable this calibration?</p><p>Flagged calibrations will no longer have an effect.</p><p>   NO    <span style="background-color:white;color:black;"> SI </span></p></div><p>Comparirà in rosso e non verrà più usata nel calcolo.</p><img src="'+p+'" style="zoom:75%;"><h3 id="reset-all-calibrations" tabindex="-1">Azzerare tutte le calibrazioni <a class="header-anchor" href="#reset-all-calibrations" aria-label="Permalink to &quot;Azzerare tutte le calibrazioni {#reset-all-calibrations}&quot;">​</a></h3><p>Questo metodo vale solo per i sensori che supportano la calibrazione di xDrip.</p><p><strong>Non usarlo per i sensori solo a calibrazione nativa (G6 nuovi, G7, 1, 1+ ecc.).</strong></p><p>Quando diventa chiaro che le calibrazioni attuali sono sbagliate, o se non hai dati dopo aver calibrato, il modo più rapido per ripartire da zero con la calibrazione (Calibrazione iniziale) è azzerare tutte le calibrazioni.</p><p>Dal menu principale, Stop Sensore.</p><div class="admonition xdrip"><p class="admonition-title"><img src="'+d+'" style="zoom:75%;"></p><p> Stop Sensore</p></div><p><strong>Non fermare il sensore</strong>: azzera solo tutte le calibrazioni.</p><div class="admonition xdripitem"><p class="admonition-title"><img src="'+m+'" style="zoom:75%;"> Arresto Sensore <span class="symbol"></span></p><p> Ferma il tuo sensore solo quando pensi di rimuoverlo, altrimenti lascialo avviato!</p><p>       <span style="background-color:white;color:black;"> NON FERMARE, RESETTA SOLO TUTTE LE CALIBRAZIONI </span></p></div><div class="admonition xdripitem"><p class="admonition-title">Sei sicuro?</p><p> Eliminare e resettare le calibrazioni per questo sensore?</p><p>       NO    <span style="background-color:white;color:black;"> SI </span></p></div><p>xDrip ti riporterà alla <a href="#first-calibration">calibrazione iniziale</a>. Assicurati di eseguire questa operazione con glicemia stabile, nell&#39;intervallo.</p><br><p><a href="https://github.com/NightscoutFoundation/xDrip/releases/tag/2026.11.21" target="_blank" rel="noreferrer"><em>Ultima modifica 23/11/2026</em></a></p>',69)])])}const N=u(h,[["render",z]]);export{C as __pageData,N as default};
